<template>
 <el-dialog title="新建库存检查" :visible="visible" width="960px" append-to-body :close-on-click-modal="false" custom-class="inventory-check-create" @close="$emit('close')">
  <el-form label-position="top">
   <h3>1. 选择货主与实仓</h3>
   <el-form-item label="查询仓库" required><el-select v-model="form.store_code" filterable placeholder="选择货主和实仓，系统自动合并该实仓下全部虚仓" @change="loadScope"><el-option v-for="w in warehouseChoices" :key="w.store_code" :value="w.store_code" :label="`${w.owner_name || w.owner_code} / ${w.real_name}`"/></el-select></el-form-item>
   <div v-loading="scopeLoading" class="scope-summary"><template v-if="range"><b>{{ range.owner_code }} · {{ range.real_store }}</b><p>合并 {{ range.stores.length }} 个虚仓：{{ range.stores.join('、') }}</p></template><span v-else>选仓后显示实际比较范围</span></div>
   <h3>2. 选择检查范围</h3>
   <div class="scope-cards"><button type="button" :class="{active:form.scope_mode==='FULL'}" @click="form.scope_mode='FULL'"><b>全仓检查</b><span>自动收集本仓商品，无需逐个选择</span></button><button type="button" :class="{active:form.scope_mode==='SELECTED'}" @click="form.scope_mode='SELECTED'"><b>指定商品检查</b><span>输入SKU，检查指定商品全部批次</span></button></div>
   <template v-if="form.scope_mode==='FULL'">
    <el-alert title="包含零库存记录、冻结与业务占用库存；有库存的停用商品也会检查。仅查询，不预占或调整库存。" type="info" :closable="false"/>
    <el-form-item label="商品清单覆盖"><el-radio-group v-model="form.coverage"><el-radio label="OMS_LIST">OMS商品清单</el-radio><el-radio label="OMS_WMS_LIST">OMS＋仓库完整清单（导入）</el-radio></el-radio-group></el-form-item>
    <p class="hint">OMS清单覆盖本仓库存记录与待处理单据中的商品，无法发现仓库独有商品。当前连接未验证自动枚举仓库全量商品的能力。</p>
    <template v-if="form.coverage==='OMS_WMS_LIST'"><el-form-item label="仓库导出的完整SKU清单（UTF-8 CSV，仅一列sku_sn）" required><input ref="manifestFile" type="file" accept=".csv,.txt" style="display:none" @change="readFile"><el-button size="small" @click="$refs.manifestFile.click()">选择仓库清单文件</el-button><span v-if="manifest.length">已导入 {{ manifest.length }} 个SKU · {{ fileName }}</span></el-form-item><el-input v-model.trim="form.warehouse_list_evidence" maxlength="500" placeholder="记录导出时间、货主实仓和清单来源，便于复核"/><el-checkbox v-model="form.warehouse_list_confirmed">已核对清单属于上方货主实仓，包含全部商品及零库存商品</el-checkbox></template>
    <div class="summary"><b>提交后后台执行</b><p>先收集商品，再逐个查询完整批次。可关闭页面、停止后继续，也可单独重试失败商品。</p><p>全仓结果用于发现差异；调整前须为选定商品生成最新复查。</p></div>
   </template>
   <template v-else><el-form-item label="从本仓库存商品中选择"><el-select v-model="picked" multiple filterable remote :remote-method="searchGoods" :loading="goodsLoading" :disabled="!range" placeholder="输入SKU前缀搜索，最多展示30种；无库存记录的商品可在下方粘贴" @change="appendPicked"><el-option v-for="g in goods" :key="g.sku_sn" :value="g.sku_sn" :label="g.sku_sn+' · '+(g.goods_name||'资料待确认')"/></el-select></el-form-item><el-form-item label="完整SKU编码" required><el-input v-model="form.skuText" type="textarea" :rows="4" placeholder="粘贴SKU，每行一个，也支持逗号分隔；最多100个"/><p class="hint">当前填写 {{ parsedCount }} 个不同SKU。合并所有虚仓，保留商品批次和正次品明细。</p></el-form-item><el-form-item label="查询方式"><el-radio-group v-model="form.method"><el-radio label="stock.query" :disabled="parsedCount>1">单商品完整批次分页</el-radio><el-radio label="inventory.query">多商品查询</el-radio></el-radio-group><p class="hint">多商品结果如缺少批次，请对该商品使用完整批次分页复查。</p></el-form-item></template>
  </el-form>
  <div slot="footer"><el-button @click="$emit('close')">取消</el-button><el-button type="primary" :loading="saving" :disabled="!range||scopeLoading" @click="submit">{{ form.scope_mode==='FULL'?'提交全仓检查':'提交库存检查' }}</el-button></div>
 </el-dialog>
</template>
<script>
import * as api from '@/api/purchase/warehouseControl'
import { skuList, warehouseCsv } from '@/utils/inventoryCheck'
export default {
 props:{visible:Boolean,warehouses:{type:Array,default:()=>[]},initial:{type:Object,default:()=>({})}},
 data:()=>({form:{},range:null,scopeLoading:false,scopeSequence:0,saving:false,manifest:[],fileName:'',picked:[],goods:[],goodsLoading:false,goodsSequence:0}),
 computed:{warehouseChoices(){const grouped={};this.warehouses.forEach(w=>{const key=w.owner_code+'\u001f'+w.real_store_code;if(!grouped[key]||w.store_code===this.form.store_code)grouped[key]=w});return Object.values(grouped)},parsedCount(){try{return skuList(this.form.skuText).length}catch(_){return [...new Set(String(this.form.skuText||'').split(/[\s,，;；]+/).filter(Boolean))].length}}},
 watch:{visible(v){if(v){this.form={request_key:'CHECK_'+Date.now()+'_'+Math.random().toString(36).slice(2),store_code:this.initial.source_store||'',scope_mode:this.initial.scope_mode||'FULL',coverage:'OMS_LIST',skuText:this.initial.skuText||'',method:this.initial.method||'stock.query',warehouse_list_confirmed:false,warehouse_list_evidence:''};this.manifest=[];this.fileName='';this.picked=[];this.goods=[];this.goodsSequence++;this.range=null;if(this.form.store_code)this.loadScope()}else this.scopeSequence++}},
 beforeDestroy(){this.scopeSequence++;this.goodsSequence++},
 methods:{async searchGoods(keyword){const seq=++this.goodsSequence;this.goods=[];if(!keyword.trim()||!this.form.store_code)return;this.goodsLoading=true;try{const r=await api.checkGoods({store_code:this.form.store_code,keyword});if(seq===this.goodsSequence)this.goods=r.data||[]}finally{if(seq===this.goodsSequence)this.goodsLoading=false}},appendPicked(){const text=[this.form.skuText,...this.picked].join('\n');try{this.form.skuText=skuList(text).join('\n')}catch(e){this.$message.warning(e.message)}this.picked=[]},async loadScope(){const seq=++this.scopeSequence;this.range=null;this.picked=[];this.goods=[];this.goodsSequence++;this.scopeLoading=true;try{const r=await api.checkScope(this.form.store_code);if(seq===this.scopeSequence)this.range=r.data}finally{if(seq===this.scopeSequence)this.scopeLoading=false}},async readFile(event){this.manifest=[];this.fileName='';const file=event.target.files[0];if(!file)return;try{if(file.size>4*1024*1024)throw new Error('文件最多4MB');const rows=warehouseCsv(await file.text());this.manifest=rows;this.fileName=file.name}catch(e){this.$message.error(e.message)}},async submit(){let body={request_key:this.form.request_key,store_code:this.form.store_code,scope_mode:this.form.scope_mode};try{if(!this.range)throw new Error('请先选择检查仓库');if(body.scope_mode==='FULL'){if(this.form.coverage==='OMS_WMS_LIST'){if(!this.manifest.length||!this.form.warehouse_list_confirmed||!this.form.warehouse_list_evidence)throw new Error('请导入仓库完整清单，记录来源并确认覆盖');body={...body,warehouse_skus:this.manifest,warehouse_list_evidence:this.form.warehouse_list_evidence,warehouse_list_confirmed:true}}}else{body={...body,skus:skuList(this.form.skuText),method:this.form.method};if(body.method==='stock.query'&&body.skus.length!==1)throw new Error('多个商品请选择多商品查询')}}catch(e){return this.$message.warning(e.message)}this.saving=true;try{const id=(await api.create('reconciliations',body)).data;this.$emit('created',id)}finally{this.saving=false}}}
}
</script>
<style scoped>
h3{font-size:17px;margin:12px 0 18px}.el-select{width:100%}.scope-summary,.summary{background:#f3f6fb;padding:16px 20px;border-radius:8px;line-height:1.7}.scope-summary p,.summary p{margin:6px 0;color:#66788e;font-size:13px}.scope-cards{display:flex;gap:14px;margin-bottom:20px}.scope-cards button{flex:1;background:white;border:1px solid #dce3ee;border-radius:8px;padding:18px;text-align:left;cursor:pointer;color:#34455d}.scope-cards button.active{border:2px solid #1682ef;background:#f0f7ff;padding:17px}.scope-cards b,.scope-cards span{display:block}.scope-cards span,.hint{font-size:13px;color:#74849a;line-height:1.8;margin-top:8px}.summary{margin-top:20px}.el-checkbox{display:block;margin-top:16px;white-space:normal}.el-radio-group{display:flex;flex-wrap:wrap;gap:16px}.el-radio{margin:0}
</style>
